#!/usr/bin/env bash
# nec2++ (tmolteno/necpp) -> WASI command module (wasm32-wasip1, wasm exceptions) -> web/wasm/nec2pp.wasm
#
# env:
#   NECPP_DIR  necpp clone (default ../../tmolteno/necpp)
#   WASI_SDK   wasi-sdk >= 33 (default /opt/wasi-sdk)
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
NECPP_DIR="${NECPP_DIR:-$ROOT/../../tmolteno/necpp}"
WASI_SDK="${WASI_SDK:-/opt/wasi-sdk}"
S="$NECPP_DIR/src"
R="$WASI_SDK/share/wasi-sysroot"
B="$ROOT/build/wasm"
OUT="$ROOT/web/wasm/nec2pp.wasm"

mkdir -p "$B" "$(dirname "$OUT")"

# config.h (normally generated by CMake)
VERSION=$(grep -A4 'project(necpp' "$NECPP_DIR/CMakeLists.txt" | sed -n 's/.*VERSION *\([0-9.]*\).*/\1/p' | head -1)
cat > "$B/config.h" <<EOF
#ifndef CONFIG_H
#define CONFIG_H
#define NECPP_VERSION "${VERSION:-unknown}"
#define NECPP_BUILD_DATE "$(date +%F)"
#endif
EOF

# WASI has no signals / process clocks: reuse the __EMSCRIPTEN__ stubs for __wasi__
for f in misc.cpp nec2cpp.cpp; do
  sed 's/defined(__EMSCRIPTEN__)/(defined(__EMSCRIPTEN__) || defined(__wasi__))/g' "$S/$f" > "$B/$f"
done

SRCS="c_evlcom.cpp c_geometry.cpp c_ggrid.cpp c_plot_card.cpp electromag.cpp libNEC.cpp
  matrix_algebra.cpp nec_context.cpp nec_exception.cpp nec_ground.cpp nec_output.cpp
  nec_radiation_pattern.cpp nec_results.cpp nec_structure_currents.cpp XGetopt.cpp"

# libc++ in wasi-sdk eh/ uses new (exnref) exception handling -> match it
CXX="$WASI_SDK/bin/clang++ --target=wasm32-wasip1 --sysroot=$R"
CXXFLAGS="-std=c++17 -O2 -DNDEBUG -fwasm-exceptions -mllvm -wasm-use-legacy-eh=false -D_WASI_EMULATED_SIGNAL -I$B -I$S -isystem $S/eigen"

{ echo "$B/misc.cpp"; echo "$B/nec2cpp.cpp"; for f in $SRCS; do echo "$S/$f"; done; } |
  xargs -P "$(nproc)" -I{} sh -c '$0 $1 -c "{}" -o "$2/$(basename "{}" .cpp).o"' "$CXX" "$CXXFLAGS" "$B"

$CXX -fwasm-exceptions -nostdlib++ "$B"/*.o \
  -L"$R/lib/wasm32-wasip1/eh" -lc++ -lc++abi -lunwind -lwasi-emulated-signal \
  -Wl,-z,stack-size=8388608 -Wl,--strip-all \
  -o "$OUT"

echo "$OUT $(stat -c %s "$OUT") bytes, necpp $(git -C "$NECPP_DIR" rev-parse --short HEAD)"
